-- Steady backend foundation. No live data, sign-in changes or production cutover.
-- Text JSON/date fields intentionally retain the existing serialization contract.
-- All browser roles are read-only until transaction-safe write APIs are ported.

CREATE TABLE public."application_events" (
  "sequence" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "operation_id" text NOT NULL,
  "owner_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  "application_id" text NOT NULL,
  "action" text NOT NULL,
  "snapshot" text NOT NULL,
  "previous" text,
  "happened_at" text NOT NULL,
  "local_date" text NOT NULL,
  "request" text NOT NULL
);
CREATE INDEX "idx_application_events_owner_sequence" ON public."application_events" ("owner_id", "sequence");
CREATE UNIQUE INDEX "idx_application_events_operation" ON public."application_events" ("operation_id");
ALTER TABLE public."application_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."application_events" FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."application_events" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public."application_events" TO authenticated;
GRANT ALL ON TABLE public."application_events" TO service_role;
CREATE POLICY owner_read ON public."application_events" FOR SELECT TO authenticated USING ((SELECT auth.uid()) = owner_id);

CREATE TABLE public."applications" (
  "id" text PRIMARY KEY NOT NULL,
  "owner_id" uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  "institution" text NOT NULL,
  "country" text NOT NULL DEFAULT '',
  "project_title" text NOT NULL DEFAULT '',
  "supervisor" text NOT NULL DEFAULT '',
  "link" text NOT NULL DEFAULT '',
  "deadline" text,
  "notes" text NOT NULL DEFAULT '',
  "next_action" text NOT NULL DEFAULT '',
  "stage" text NOT NULL DEFAULT 'Shortlisted',
  "checklist" text NOT NULL DEFAULT '[]',
  "submission_date" text,
  "submission_task_id" text,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  "version" integer NOT NULL DEFAULT 1,
  "opportunity" text NOT NULL DEFAULT '{}'
);
CREATE INDEX "idx_applications_owner" ON public."applications" ("owner_id");
ALTER TABLE public."applications" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."applications" FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."applications" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public."applications" TO authenticated;
GRANT ALL ON TABLE public."applications" TO service_role;
CREATE POLICY owner_read ON public."applications" FOR SELECT TO authenticated USING ((SELECT auth.uid()) = owner_id);

