-- Identity mapping is administrative; an email match must never silently merge accounts.
CREATE SCHEMA steady_private;
REVOKE ALL ON SCHEMA steady_private FROM PUBLIC, anon, authenticated;
CREATE TABLE steady_private.identity_mappings (
  source_site_id text NOT NULL,
  source_owner_id text NOT NULL,
  auth_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  verified_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (source_site_id, source_owner_id),
  UNIQUE (source_site_id, auth_user_id)
);
ALTER TABLE steady_private.identity_mappings ENABLE ROW LEVEL SECURITY;
ALTER TABLE steady_private.identity_mappings FORCE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE steady_private.identity_mappings FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, anon, authenticated;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
